"96\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"420\" cy=\"123\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"420\" cy=\"150\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"447\" cy=\"15\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"447\" cy=\"42\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"447\" cy=\"69\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"447\" cy=\"96\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"447\" cy=\"123\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"447\" cy=\"150\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"474\" cy=\"15\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"474\" cy=\"42\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"474\" cy=\"69\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"474\" cy=\"96\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"474\" cy=\"123\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"474\" cy=\"150\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"501\" cy=\"15\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"501\" cy=\"42\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"501\" cy=\"69\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"501\" cy=\"96\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"501\" cy=\"123\" r=\"3\" fill=\"#1e293b\"/><circle cx=\"501\" cy=\"150\" r=\"3\" fill=\"#1e293b\"/><text x=\"69\" y=\"101\" font-size=\"13\" text-anchor=\"middle\" fill=\"#1e293b\" font-weight=\"bold\">Kare</text><text x=\"258\" y=\"125\" font-size=\"13\" text-anchor=\"middle\" fill=\"#1e293b\" font-weight=\"bold\">Üçgen</text></svg></div><p>Karenin alanı (16x² − 32x + 16) cm²’dir (x &gt; 1).</p><p><b>Buna göre dik üçgenin çevresinin uzunluğunu santimetre cinsinden veren ifade aşağıdakilerden hangisidir?</b></p>",
